using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionTimingTests { [Fact] public void Timings_are_contiguous_nonoverlapping_and_exact(){var p=DocumentaryMediaProjectionFixture.Complete(DocumentaryMediaProjectionFixture.Orion());foreach(var v in p.Variants){long end=0;foreach(var s in v.Scenes){Assert.Equal(end,s.Timing.PlannedStartMilliseconds);Assert.True(s.Timing.PlannedEndMilliseconds>s.Timing.PlannedStartMilliseconds);Assert.Equal(s.Timing.PlannedEndMilliseconds-s.Timing.PlannedStartMilliseconds,s.Timing.PlannedDurationMilliseconds);Assert.True(s.Timing.PlannedDurationMilliseconds>=s.Timing.NarrationDurationMilliseconds);end=s.Timing.PlannedEndMilliseconds;}Assert.Equal(end,v.PlannedDurationMilliseconds);}} }
